 .chapter-ribbon,.option-row{position:relative;display:flex;align-items:center;gap:16px;min-height:65px;padding:10px 23px 10px 18px;box-sizing:border-box;isolation:isolate}.chapter-ribbon{background:linear-gradient(100deg,#cceafa,#93bdf3c9);clip-path:polygon(4px 0,calc(100% - 20px) 0,100% 50%,calc(100% - 20px) 100%,0 100%);border-left:3px solid #3d73ff}.diamond{font-size:32px;font-family:Georgia,serif;line-height:1;flex:none}.chapter-ribbon strong{font-size:19px;font-weight:500;letter-spacing:.1em}.chapter-ribbon small{display:block;font-size:8px;letter-spacing:.13em;margin-top:5px}.ribbon-arrow{margin-left:auto;font-size:28px;color:#3f7aff}
