 .primary{display:flex;align-items:center;gap:20px;width:310px;max-width:100%;min-height:58px;background:linear-gradient(110deg,#2c54ec,#569eff);color:white;text-align:left;padding:9px 24px;clip-path:polygon(0 0,calc(100% - 23px) 0,100% 50%,calc(100% - 23px) 100%,0 100%);font-size:18px;letter-spacing:.13em;transition:filter .16s,translate .16s}.primary>span:first-child{font:38px Georgia,serif;line-height:1}.primary small{display:block;font-size:8px;letter-spacing:.18em;margin-top:4px}.primary b{margin-left:auto;font-size:33px;font-weight:300}.primary:hover,.primary:focus-visible{filter:brightness(1.12);translate:3px 0;outline:none;box-shadow:inset 0 0 0 2px #173ce9}.primary:disabled{background:#b2c0d3;color:#f2f5fa;cursor:default;filter:none;translate:none}
